INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_traditional_math', '推論', NULL, '上記A〜Dの命題が成り立つとき、正しい命題の組み合わせとして最も適切なものを、次の5つの選択肢から1つ選びなさい。
好みについては、好きか嫌いかの2択とします。

A　「犬」が好きな人は、全員「猫」が嫌いである
B　「猫」が嫌いな人は、全員「鳥」が好きである
C　「鳥」が好きな人は、全員「魚」が嫌いである
D　「うさぎ」が好きな人は、全員「魚」も好きである', NULL, '["1・2・3","1・2・5","1・2","2・5","1・3・4"]', 1, '["各命題とその対偶を整理すると、次の鎖ができます。","犬好き→（A）猫嫌い→（B）鳥好き→（C）魚嫌い→（Dの対偶）うさぎ嫌い","つまり「犬が好きな人は、鳥が好きで、魚が嫌いで、うさぎも嫌い」といえます。よって選択肢1は正しい。","また、Dの対偶（魚嫌い→うさぎ嫌い）とCの対偶（魚好き→鳥嫌い）、Bの対偶（鳥嫌い→猫好き）、Aの対偶（猫好き→犬嫌い）をつなげると、","うさぎ好き→（D）魚好き→（Cの対偶）鳥嫌い→（Bの対偶）猫好き→（Aの対偶）犬嫌い","となるので、選択肢2も正しい。同じ鎖の一部として、魚好き→鳥嫌い→猫好き なので、選択肢5も正しい。","選択肢3（猫好き→鳥嫌い）は、Bの逆（鳥好き→猫嫌いではなく、猫嫌い→鳥好き、が正しい命題）であり、逆は必ずしも成り立たないため誤りです。","選択肢4（鳥嫌い→猫嫌い）も、正しくは「鳥嫌い→猫好き」（Bの対偶）であり、真逆の内容なので誤りです。","よって、正解は1・2・5・・・（答）となります。","元の設問では複数選択可（解答は「1・2・5」）だったため、正しい組み合わせ「1・2・5」を1つの選択肢として選ぶ5択形式に再構成した。個々の選択肢の正誤根拠は解説を参照。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB従来型非言語: 推論）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_traditional_math', '推論', NULL, '上記A〜Dの命題が成り立つとき、正しい命題の組み合わせとして最も適切なものを、次の5つの選択肢から1つ選びなさい。
習慣については、する・しないの2択とします。

A　早起きをする人は、全員朝食を食べる
B　朝食を食べない人は、全員運動をしない
C　運動をする人は、全員間食をしない
D　夜更かしをする人は、全員間食をする', NULL, '["1","2","1・2","1・2・3","3・4・5"]', 2, '["各命題の対偶も含めて整理します（Dの対偶：間食しない→夜更かししない、Cの対偶：間食する→運動しない）。","夜更かしする→（D）間食する→（Cの対偶）運動しない、という鎖ができるので、選択肢1は正しい。","また、この鎖の対偶を考えると「運動する→間食しない→夜更かししない」となり（C、Dの対偶の組み合わせ）、選択肢2も正しい。","選択肢3・4・5は、「早起き」「朝食」のグループと「運動」「間食」「夜更かし」のグループの間に、直接つながる命題が存在しないため、確実にはいえません（早起き→朝食までしか鎖がつながらず、朝食から先の情報はないため）。","よって、正解は1・2・・・（答）となります。","元の設問では複数選択可（解答は「1・2」）だったため、正しい組み合わせ「1・2」を1つの選択肢として選ぶ5択形式に再構成した。個々の選択肢の正誤根拠は解説を参照。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB従来型非言語: 推論）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_traditional_math', '推論', NULL, '上記A〜Cの命題が成り立つとき、正しい命題の組み合わせとして最も適切なものを、次の5つの選択肢から1つ選びなさい。

A　「山登り」が好きな人は、全員「キャンプ」も好きである
B　「釣り」が好きな人は、全員「山登り」が嫌いである
C　「バーベキュー」が好きな人は、全員「釣り」も好きである', NULL, '["1・2","1・3","1・2・3","1・2・3・4","4・5"]', 2, '["バーベキュー好き→（C）釣り好き→（B）山登り嫌い、という鎖ができるので、選択肢1は正しい。","また、Bの対偶（山登り好き→釣り嫌い）とCの対偶（釣り嫌い→バーベキュー嫌い）をつなげると、山登り好き→釣り嫌い→バーベキュー嫌い となるので、選択肢2も正しい。","Aの対偶（キャンプ嫌い→山登り嫌い）は、Aそのものの対偶として直接成り立つので、選択肢3も正しい。","選択肢4（釣り好き→キャンプ嫌い）は、「釣り」と「キャンプ」を直接つなぐ命題がないため、確実にはいえません。","選択肢5（山登り嫌い→釣り好き）は、Bの逆であり、逆は必ずしも成り立たないため誤りです。","よって、正解は1・2・3・・・（答）となります。","元の設問では複数選択可（解答は「1・2・3」）だったため、正しい組み合わせ「1・2・3」を1つの選択肢として選ぶ5択形式に再構成した。個々の選択肢の正誤根拠は解説を参照。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB従来型非言語: 推論）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_traditional_math', '推論', NULL, '上記A〜Dの命題が成り立つとき、正しい命題の組み合わせとして最も適切なものを、次の5つの選択肢から1つ選びなさい。

A　早朝勉強をする人は、全員夜型ではない
B　夜型でない人は、全員カフェインを摂取する
C　カフェインを摂取する人は、全員昼寝をしない
D　昼寝をする人は、全員夜型である', NULL, '["1・2","2・3","1・2・3","1・2・3・5","4・5"]', 2, '["早朝勉強する→（A）夜型でない→（B）カフェイン摂取する、という鎖ができるので、選択肢1は正しい。","Dの対偶（夜型でない→昼寝しない）を使うと、早朝勉強する→夜型でない→昼寝しない、ともいえます。この鎖の対偶を考えると、昼寝する→早朝勉強しない となるので、選択肢2も正しい。","Bの対偶（カフェイン摂取しない→夜型）とAの対偶（夜型→早朝勉強しない）をつなげると、カフェイン摂取しない→夜型→早朝勉強しない となるので、選択肢3も正しい。","選択肢4は、上で示した「早朝勉強する→昼寝しない」と正反対の内容であり誤りです。","選択肢5（夜型→カフェイン摂取する）は、Bの前提が「夜型でない人」についてのものであり、「夜型の人」についての情報は与えられていないため、確実にはいえません。","よって、正解は1・2・3・・・（答）となります。","元の設問では複数選択可（解答は「1・2・3」）だったため、正しい組み合わせ「1・2・3」を1つの選択肢として選ぶ5択形式に再構成した。個々の選択肢の正誤根拠は解説を参照。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB従来型非言語: 推論）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_traditional_math', '推論', NULL, '上記A〜Dの命題が成り立つとき、正しい命題の組み合わせとして最も適切なものを、次の5つの選択肢から1つ選びなさい。

A　「読書」が好きな人は、全員「ゲーム」が嫌いである
B　「ゲーム」が嫌いな人は、全員「散歩」が好きである
C　「散歩」が好きな人は、全員「料理」が嫌いである
D　「昼寝」が好きな人は、全員「料理」も好きである', NULL, '["1・2","1・3","1・2・3","1・2・3・5","4・5"]', 2, '["読書好き→（A）ゲーム嫌い→（B）散歩好き→（C）料理嫌い、そしてDの対偶（料理嫌い→昼寝嫌い）をつなげると、読書好き→…→昼寝嫌い となるので、選択肢1は正しい。","昼寝好き→（D）料理好き→（Cの対偶）散歩嫌い→（Bの対偶）ゲーム好き、という鎖ができるので、選択肢2も正しい。","料理好き→（Cの対偶）散歩嫌い→（Bの対偶）ゲーム好き→（Aの対偶）読書嫌い、という鎖ができるので、選択肢3も正しい。","選択肢4は、選択肢1の鎖の一部「散歩好き→料理嫌い→昼寝嫌い」と正反対であり誤りです。","選択肢5（ゲーム好き→散歩嫌い）は、「ゲームが好きな人」について直接言及した命題がないため、確実にはいえません。","よって、正解は1・2・3・・・（答）となります。","元の設問では複数選択可（解答は「1・2・3」）だったため、正しい組み合わせ「1・2・3」を1つの選択肢として選ぶ5択形式に再構成した。個々の選択肢の正誤根拠は解説を参照。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB従来型非言語: 推論）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_traditional_math', '推論', NULL, 'A〜Dの4組が駅伝を行った。最終走者について、次のア〜エのことがわかっているとき、確実にいえるのはどれか。

ア：A組は、C組だけを追い越し、B組とD組に追い越された。
イ：B組は、A組、C組、D組の3人を追い越し、誰にも追い越されなかった。
ウ：C組がたすきを受け取ったのは、1位だった。
エ：D組は、B組だけに追い越され、A組とC組を追い越した。', NULL, '["A組は、D組を追い越した。","B組は、C組を追い越さなかった。","B組は、1位でゴールした。","C組は、2位でゴールした。","D組は、4位でスタートした。"]', 2, '["「Xが追い越した」＝Xはスタート時に相手より後ろにいて、ゴール時に相手より前にいた、という意味です。","ア・イ・エより、スタート順について「BはA・C・Dより後ろから、DはA・Cより後ろから、AはCより後ろから」出発したことがわかります。ウより、Cが1位スタートなので、スタート順はC→A→D→Bと確定します。","また、ゴール順については「BはA・C・Dより前で、DはA・Cより前で、AはCより前で」ゴールしたことがわかるので、ゴール順はB→D→A→Cと確定します。","これより、B組は1位でゴールしています。","よって、正解は3・・・（答）となります。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB従来型非言語: 推論）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_traditional_math', '推論', NULL, 'A〜Dの4組が駅伝を行った。最終走者について、次のア〜エのことがわかっているとき、確実にいえるのはどれか。

ア：A組は、誰も追い越さず、3人に追い越された。
イ：C組は、A組、B組、D組の3人を追い越し、誰にも追い越されなかった。
ウ：B組がたすきを受け取ったのは、3位だった。
エ：D組は、2人に追い越され、1人（A組）を追い越した。', NULL, '["A組は、1位でスタートした。","C組は、2位でゴールした。","D組は、B組を追い越した。","B組は、4位でゴールした。","A組は、D組を追い越した。"]', 0, '["アより、B・C・Dの3人はA組より後ろからスタートし、A組より前でゴールしたことがわかります。よって、Aは1位でスタートし、4位でゴールしたことになります。","イより、C組は他の3組より後ろからスタートして、他の3組より前でゴールしています。よって、Cは4位でスタートし、1位でゴールしたことになります。","ウより、Bは3位でスタートしたので、残るDは2位でスタートしたことになります。","エより、D組はA組だけを追い越しており（A組はDより前からスタートし、Dより後ろでゴールした関係）、B組・C組は追い越していません。D組はB・C組に追い越されているので、B・C組はゴールでDより前にいます。C組は1位ゴールなので、残るゴール順は、D組がB組より前になるように決まり、B組は最下位（4位）でゴールしたことがわかります。","以上より、スタート順は A1・D2・B3・C4、ゴール順は C1・B2・D3・A4 と確定します（Aは1位スタート・4位ゴール、Cは4位スタート・1位ゴール、Bは3位スタート・2位ゴール、Dは2位スタート・3位ゴール）。","よって、Aは1位でスタートしています。正解は1・・・（答）となります。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB従来型非言語: 推論）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_traditional_math', '推論', NULL, 'A〜Dの4組が駅伝を行った。最終走者について、次のア〜エのことがわかっているとき、確実にいえるのはどれか。

ア：A組は、B組とC組の2人を追い越し、誰にも追い越されなかった。
イ：C組は、B組を追い越し、A組に追い越された。
ウ：D組がたすきを受け取ったのは、4位だった。また、D組は、B組だけを追い越し、誰にも追い越されなかった。', NULL, '["A組は、3位でスタートした。","B組は、2位でゴールした。","C組は、D組を追い越した。","D組は、1位でゴールした。","A組は、C組に追い越された。"]', 0, '["アより、A組はB組・C組より後ろからスタートしています。ウより、D組は4位（最後尾）スタートです。","ウより、D組はB組だけを追い越しており、A組・C組を追い越していません。D組は最後尾スタートなので、A組・C組より必ず後ろからスタートしていますが、A組・C組を追い越していない（＝ゴールでも彼らより後ろのまま）ということは、A組・C組との順位関係はスタートからゴールまで変わらなかったことになります。","以上より、スタート順は、B組が1位、C組が2位、A組が3位、D組が4位と決まります（アより、A組はC組より後ろからスタート）。","ゴール順は、A組が誰にも追い越されず、B組・C組を追い越したのでA組が1位。D組は誰にも追い越されておらず、B組だけを追い越し、A・Cとの順位関係は変わらないので、Aより後ろ・Cより後ろのままの位置になり、C組が2位、D組が3位、B組が4位（最下位）となります。","以上より、スタート：B1,C2,A3,D4／ゴール：A1,C2,D3,B4 と確定します。","よって、正解は1・・・（答）となります。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB従来型非言語: 推論）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_traditional_math', '推論', NULL, 'P〜Sの4組が駅伝を行った。最終走者について、次のア〜エのことがわかっているとき、確実にいえるのはどれか。

ア：P組は、2人（Q組とS組）を追い越し、誰にも追い越されなかった。
イ：Q組は、S組を追い越したが、P組に追い越された。
ウ：R組がたすきを受け取ったのは、4位だった。
エ：S組は、誰も追い越さず、2人（P組とQ組）に追い越された。', NULL, '["P組は、3位でスタートした。","Q組は、S組を追い越さなかった。","R組は、3位でゴールした。","S組は、1位でゴールした。","P組は、Q組に追い越された。"]', 0, '["ウより、R組は4位スタートです。R組を除く3組について考えると、アより「PはQ・Sより後ろからスタート」、イより「QはSより後ろからスタート」なので、スタート順は、S組が1位、Q組が2位、P組が3位となります（R組は4位）。","また、R組は最下位スタートですが、P・Q・Sのいずれからも追い越されておらず（ア・イ・エより、追い越したのはP・Q同士とP・Q対Sの関係のみ）、R組自身も誰も追い越していないことが読み取れるので、R組はスタート順のままゴールし、4位でゴールしたことになります。","残る3組のゴール順は、アより「PはQ・Sより前でゴール」、イより「QはSより前でゴール」なので、P組が1位、Q組が2位、S組が3位、R組が4位となります。","以上より、スタート：S1,Q2,P3,R4／ゴール：P1,Q2,S3,R4 と確定します。","よって、正解は1・・・（答）となります。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB従来型非言語: 推論）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_traditional_math', '推論', NULL, 'P〜Sの4人が受講している講習では、受講者が1時間目、2時間目、3時間目に物理、化学、生物、地学の4科目からそれぞれ任意の1科目を選んで受講することになっている。次のことがわかっているとき、確実にいえるのはどれか。
ただし、同一の科目を複数回受講した者はいなかったものとする。

ア：PとQは、1時間目は互いに異なる科目を受講したが、2時間目は一緒に物理を、3時間目は一緒に化学を受講した。
イ：R、Sは、他の人と、同じ時間には同じ科目を受講しなかった。
ウ：Rは化学を受講しなかった。また、Sは生物を受講しなかった。', NULL, '["Sが3時間目に受講した科目は、Pが2時間目に受講した科目と同じだった。","Qが1時間目に受講した科目は、Rが1時間目に受講した科目と同じだった。","Rは1時間目に地学を受講した。","Qは3時間目に地学を受講した。","Pは1時間目に生物を受講した。"]', 0, '["条件アより、P、Qは2時間目に物理、3時間目に化学を受講し、1時間目には残る生物・地学を1人ずつ受講したとわかります（どちらがどちらかは確定しません）。","条件イより、R、Sは1時間目にP・Qと異なる科目、すなわち物理・化学のいずれかを、互いにも異なる科目で受講したことになります。","条件ウより、Rは化学を受講していないので、1時間目にRは物理を、Sは化学を受講したことになります。","2時間目も同様に、P・Qが使っている物理を避け、R・Sで異なる科目を受講します。Rは1時間目に物理を使っているので、2時間目は物理以外で化学・生物・地学のいずれかですが、条件ウより生物は受講しないSと重ならないよう、Rは生物、Sは地学と決まります（Sは1時間目に化学を使っているため2時間目は化学以外）。","3時間目も、P・Qが使っている化学を避けます。Rは1・2時間目に物理・生物を使っているので、残るは地学。Sは1・2時間目に化学・地学を使っているので、残るは物理となります。","P・Qの1時間目が確定しないことに注意して選択肢を確認すると、確実にいえるのは1（SとPの2時間目「物理」＝Sの3時間目「物理」で一致）です。","よって、正解は1・・・（答）となります。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB従来型非言語: 推論）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_traditional_math', '推論', NULL, 'E〜Hの4人が受講している講習では、受講者が1時間目、2時間目、3時間目に美術、音楽、体育、家庭科の4科目からそれぞれ任意の1科目を選んで受講することになっている。次のことがわかっているとき、確実にいえるのはどれか。
ただし、同一の科目を複数回受講した者はいなかったものとする。

ア：EとFは、3時間目は互いに異なる科目を受講したが、1時間目は一緒に音楽を、2時間目は一緒に体育を受講した。
イ：G、Hは、他の人と、同じ時間には同じ科目を受講しなかった。
ウ：Gは家庭科を受講しなかった。また、Hは体育を受講しなかった。', NULL, '["Gは2時間目に音楽を受講した。","Hは1時間目に美術を受講した。","Eが3時間目に受講した科目は、美術だった。","Fは2時間目に家庭科を受講した。","Gは3時間目に家庭科を受講した。"]', 0, '["条件アより、E、Fは1時間目に音楽、2時間目に体育を受講し、3時間目には残る美術・家庭科を1人ずつ受講したとわかります（どちらがどちらかは確定しません）。","条件イ・ウより、G、Hは1時間目にE・Fと異なる科目（音楽以外）を、互いにも異なる科目で受講します。Gは家庭科を受講しないので、1時間目は美術・体育・家庭科のうち家庭科を除いた美術または体育ですが、後述の条件と合わせると、Gは1時間目に美術、Hは1時間目に家庭科と決まります。","2時間目も、E・Fが使っている体育を避けます。Gは1時間目に美術を使っているので2時間目は音楽か家庭科ですが、Gは家庭科を受講しないので音楽と決まります。Hは1時間目に家庭科を使っているので2時間目は音楽か美術ですが、Gと同じ音楽は使えないので美術と決まります。","3時間目は、E・Fが使っている美術・家庭科（2科目とも）を避けます。Gは1・2時間目に美術・音楽を使っているので、残るのは体育または家庭科ですが、家庭科は受講しないので体育と決まります。Hは1・2時間目に家庭科・美術を使っており、家庭科・美術を避けたうえで、Gと重ならないよう、残るのは音楽と決まります。","E・Fの3時間目が確定しないことに注意して選択肢を確認すると、確実にいえるのは1です。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB従来型非言語: 推論）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_traditional_math', '推論', NULL, 'I、J、Kの3人が受講している講習では、受講者が1時間目、2時間目、3時間目に国語、数学、英語の3科目を1科目ずつ受講することになっている（同じ人が同じ科目を2回受講することはない）。次のことがわかっているとき、確実にいえるのはどれか。

ア：Iが1時間目に受講した科目は、国語だった。
イ：Jが2時間目に受講した科目は、Iが3時間目に受講した科目と同じだった。
ウ：Kは、1時間目に英語、3時間目に数学を受講した。
エ：Jが1時間目に受講した科目は、Iが2時間目に受講した科目と同じだった。', NULL, '["Kは2時間目に国語を受講した。","Jは3時間目に英語を受講した。","Iは2時間目に数学を受講した。","Kは3時間目に英語を受講した。","Jは1時間目に数学を受講した。"]', 0, '["条件ウより、Kは1時間目に英語、3時間目に数学を受講しており、3科目とも異なる科目を受講する決まりなので、残る2時間目は国語と決まります。よって選択肢1は確実に正しいです。","条件アより、Iは1時間目が国語なので、2・3時間目は数学・英語のいずれかの組み合わせです。ここで2通りの場合分けが生じます。","【Iが2時間目に数学、3時間目に英語の場合】：条件エよりJの1時間目はIの2時間目と同じ数学、条件イよりJの2時間目はIの3時間目と同じ英語となり、Jの3時間目は残る国語となります。","【Iが2時間目に英語、3時間目に数学の場合】：同様に、Jの1時間目は英語、2時間目は数学となり、Jの3時間目は残る国語となります。","どちらの場合でも、Jの3時間目は国語で確定します。つまり選択肢2「Jは3時間目に英語」は誤りです。","一方、Iの2時間目（選択肢3）やJの1時間目（選択肢5）は、上の2つの場合で内容が変わってしまうため、確実にはいえません。選択肢4は条件ウに反するため誤りです。","よって、正解は1・・・（答）となります。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB従来型非言語: 推論）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_traditional_math', '推論', NULL, 'T〜Wの4人が受講している講習では、受講者が1時間目、2時間目、3時間目に倫理、政治経済、現代社会、歴史の4科目からそれぞれ任意の1科目を選んで受講することになっている。次のことがわかっているとき、確実にいえるのはどれか。
ただし、同一の科目を複数回受講した者はいなかったものとする。

ア：TとUは、2時間目は互いに異なる科目を受講したが、1時間目は一緒に歴史を、3時間目は一緒に倫理を受講した。
イ：V、Wは、他の人と、同じ時間には同じ科目を受講しなかった。
ウ：Vは現代社会を受講しなかった。また、1時間目に倫理、3時間目に政治経済を受講した。
エ：Wは歴史を受講しなかった。また、Wが2時間目に受講した科目は、倫理だった。', NULL, '["Wは1時間目に政治経済を受講した。","Tは2時間目に現代社会を受講した。","Vは2時間目に政治経済を受講した。","Uは3時間目に政治経済を受講した。","Wは3時間目に倫理を受講した。"]', 0, '["条件ウより、Vは1時間目に倫理、3時間目に政治経済を受講しており、現代社会を受講しないので、2時間目は残る歴史と決まります。","条件エより、Wは2時間目に倫理を受講しています。Wの1・3時間目は、条件イよりT・U・Vと同じ時間に同じ科目を受講できません。1時間目はT・U（歴史）とV（倫理）を避け、政治経済か現代社会ですが、3時間目はT・U（倫理）とV（政治経済）を避けるため、残るのは現代社会のみとなり、Wの3時間目は現代社会と決まります。すると、Wの科目の組み合わせから、1時間目は残る政治経済と決まります。","T・Uの2時間目が確定しないことに注意して選択肢を確認すると、確実にいえるのは1です。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB従来型非言語: 推論）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_traditional_math', '推論', NULL, 'あ・い・う・え・おの5人が、円形のテーブルに等間隔で中心を向いて座っている。次のことがわかっているとき、確実にいえるのはどれか。

ア：あの右隣は、いである。
イ：うの右隣は、えである。
ウ：おとうは、隣り合っていない。
エ：いとえは、隣り合っていない。', NULL, '["うの左隣は、いである。","えの右隣は、うである。","おの左隣は、あである。","あとうは、隣り合っている。","いとおは、隣り合っている。"]', 0, '["アより「あ→い」、イより「う→え」という並び（右回り）が確定しています。残るお・う・えの並べ方を考えると、いの右隣から始まる並びは「い→□→□→□→あ」の3マスに、う・え・おが入りますが、イの「う→え」の並びを崩さずに入れる方法は、①い→う→え→お→あ、②い→お→う→え→あ、の2通りが考えられます。","②の場合、おとうが隣り合ってしまい、条件ウに反します。よって①「あ→い→う→え→お→（あに戻る）」の並びに決まります。","この並びでは、いの隣はあ・う、えの隣はう・おとなり、いとえは隣り合っておらず条件エとも矛盾しません。","この並びより、うの左隣（反時計回りの隣）はいです。","よって、正解は1・・・（答）となります。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB従来型非言語: 推論）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_traditional_math', '推論', NULL, 'J、K、L、M、N、Oの6人が、左右一列に並んだ6つの席（左端が1番、右端が6番）に座っている。次のことがわかっているとき、確実にいえるのはどれか。

ア：Jは、Lより2つ右の席に座った。
イ：Kは、右端から2番目の席に座った。
ウ：NとOの間には、1人座っている。
エ：Mは、右端に座った。
オ：Oは、左端から4番目の席に座った。', NULL, '["Nは、左から2番目の席に座った。","Lは、Jの隣の席に座った。","Kは、Jの隣の席に座った。","Oは、右端に座った。","Mは、左から4番目の席に座った。"]', 0, '["エより、Mは6番（右端）。イより、Kは5番（右端から2番目）。オより、Oは4番（左端から4番目）です。","残るL、J、Nは1〜3番のいずれかに座りますが、アより、JはLより2つ右なので、（L,J）＝（1番,3番）の組み合わせしかあり得ません（Lが2番だとJは4番になりOと重複するため不可）。よって、Nは残る2番に決まります（ウの「NとOの間には1人」も、Nが2番・Oが4番で、間の3番のJ1人となり成立します）。","これより、Nは左から2番目の席に座っています。","よって、正解は1・・・（答）となります。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB従来型非言語: 推論）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_traditional_math', '推論', NULL, 'さ・し・す・せ・そ・たの6人が、円形のテーブルに等間隔で中心を向いて座っている。次のことがわかっているとき、確実にいえるのはどれか。

ア：さの正面（真向かい）は、せである。
イ：しの右隣は、すである。
ウ：たとそは、隣り合っている。
エ：しとせは、隣り合っていない。
オ：すの右隣は、せである。', NULL, '["すの正面は、たである。","さとすは、隣り合っていない。","しの正面は、そである。","せの右隣は、しである。","たとそは、正面同士である。"]', 1, '["イ・オより「し→す→せ」という並び（右回り、2マス分）が確定します。アより、さとせは正面（3つ離れた位置）の関係にあります。6人が等間隔に並ぶ円卓では、「3つ離れる」方向はどちらに数えても同じ位置になるため、さは「しの1つ左（＝せの3つ左）」の位置、つまり「さ→し」という並びになることがわかります。","以上より「さ→し→す→せ」の4人の並びが確定します。残るた・そは、この並びの続き（せの次の2席）に入りますが、順番（せ→た→そ→さ、またはせ→そ→た→さ）はウ・エの条件だけでは決まりません（どちらでも、たとそは隣り合い、しとせも隣り合いません）。","よって、た・そ以外の関係を選択肢から探すと、さとすは2つ離れており、隣り合っていません。これはた・そどちらの並びでも変わらず確実にいえます。","よって、正解は2・・・（答）となります。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB従来型非言語: 推論）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_traditional_math', '推論', NULL, 'A、B、C、Dの4人のうち1人が花瓶を割ってしまった。4人は次のように発言しており、この4つの発言のうち1つだけが嘘で、残り3つは本当のことがわかっている。

A：「花瓶を割ったのは、私（A）ではない」
B：「花瓶を割ったのは、Cである」
C：「花瓶を割ったのは、私（C）ではない」
D：「花瓶を割ったのは、Bである」

このとき、確実にいえるのはどれか。', NULL, '["花瓶を割ったのはAである。","花瓶を割ったのはBである。","花瓶を割ったのはCである。","嘘をついているのはCである。","嘘をついているのはDである。"]', 1, '["割った人物として考えられるA〜Dそれぞれについて、4つの発言の真偽を確かめます。","・Aが割った場合：A「私ではない」＝嘘、B「Cである」＝嘘、C「私ではない」＝本当、D「Bである」＝嘘。嘘が3つとなり、条件（嘘は1つ）に合いません。","・Bが割った場合：A＝本当、B＝嘘、C＝本当、D＝本当。嘘は1つ（B）で、条件に合います。","・Cが割った場合：A＝本当、B＝本当、C＝嘘、D＝嘘。嘘が2つとなり、条件に合いません。","・Dが割った場合：A＝本当、B＝嘘、C＝本当、D＝嘘。嘘が2つとなり、条件に合いません。","以上より、条件に合うのは「Bが割った場合」のみで、このとき嘘をついているのはB自身です。","よって、正解は2・・・（答）となります。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB従来型非言語: 推論）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_traditional_math', '推論', NULL, 'X、Y、Zの3人が徒競走をした（同着なし）。3人は次のように発言しており、この3つの発言のうち1つだけが嘘で、残り2つは本当のことがわかっている。

X：「私（X）は1位ではない」
Y：「Zは3位である」
Z：「Yは1位である」

このとき、確実にいえるのはどれか。', NULL, '["Yは1位でゴールした。","Xは2位でゴールした。","Zは3位でゴールした。","嘘をついているのはXである。","嘘をついているのはZである。"]', 0, '["考えられる順位のパターンをすべて確かめます（一部抜粋）。","・Y1位、Z2位、X3位の場合：X「私は1位ではない」＝本当（Xは3位）。Y「Zは3位」＝嘘（Zは2位）。Z「Yは1位」＝本当。嘘は1つ（Y）となり、条件に合います。","他のすべての順位パターンを確かめると、嘘の数が0個、2個、3個のいずれかになってしまい、条件（嘘が1つ）に合うのはこのパターンだけです。","以上より、Yが1位、Zが2位、Xが3位でゴールしたとわかり、嘘をついていたのはYです。","よって、正解は1・・・（答）となります。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB従来型非言語: 推論）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_traditional_math', '推論', NULL, 'D、E、Fの3人が、犬・猫・鳥のいずれか1匹ずつ、異なる動物を飼っている。次のことがわかっている。

・Dの動物は鳥である。
・D、E、Fの3人は以下のように発言しており、この3つの発言のうち1つだけが嘘で、残り2つは本当のことがわかっている。

D：「私（D）の動物は犬ではない」
E：「Fの動物は鳥である」
F：「私（F）の動物は猫ではない」

このとき、確実にいえるのはどれか。', NULL, '["Eの動物は猫である。","Fの動物は猫である。","嘘をついているのはDである。","嘘をついているのはFである。","Eの動物は犬である。"]', 0, '["Dの動物は鳥と決まっているので、D「私の動物は犬ではない」は本当です。よって、嘘をついているのはE・Fのいずれかです。","残るE、Fの動物は犬・猫のいずれかですが、2通り確かめます。","・E＝犬、F＝猫の場合：E「Fは鳥」＝嘘、F「私は猫ではない」＝嘘。嘘が2つとなり、条件（嘘は1つ）に合いません。","・E＝猫、F＝犬の場合：E「Fは鳥」＝嘘（Fは犬）、F「私は猫ではない」＝本当（Fは犬）。嘘は1つ（E）となり、条件に合います。","以上より、Dは鳥、Eは猫、Fは犬とわかり、嘘をついていたのはEです。","よって、正解は1・・・（答）となります。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB従来型非言語: 推論）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_traditional_math', '推論', NULL, 'a、b、c、d、eの5人の身長を比較したところ、次のことがわかった（全員の身長は異なる）。

ア：aはbより高い。
イ：cはaより高い。
ウ：dはbより低い。
エ：eはaより高く、cより低い。

このとき、身長が2番目に高いのは誰か。', NULL, '["a","b","c","d","e"]', 4, '["ア・イより、c＞a＞b という順になります。ウより、bはdより高いので、a＞b＞d、これと合わせて c＞a＞b＞d となります。","エより、eはaより高く、cより低いので、cとaの間に入ります。すなわち c＞e＞a となります。","これらをまとめると、身長の高い順に c＞e＞a＞b＞d と確定します。","2番目に高いのはeです。","よって、正解は5・・・（答）となります。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB従来型非言語: 推論）');
